/// Identity slot a feature writes to when applied. Used both as the inner
/// discriminator for `FeatureCategory::System(_)` (auto-generated species /
/// background / subclass features) and on the legacy `grants` placeholder
/// path during the migration window.
#[derive(
    Debug,
    Clone,
    Copy,
    PartialEq,
    Eq,
    PartialOrd,
    Ord,
    Hash,
    Display,
    EnumString,
    Serialize,
    Deserialize
)]
pub enum IdentitySlot {
    Subclass,
    Species,
    Background,
    Class,
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum FeatureCategory {
    #[default]
    Class,
    Origin,
    General,
    FightingStyle,
    EpicBoon,
    Generation,
    Faction,
    Dragonmark,
    /// Auto-generated by `RulesRegistry::synthesize_system_features` —
    /// one per available species / background / subclass. Each carries an
    /// assign that writes to the corresponding identity attribute.
    System(IdentitySlot),
}

impl FeatureCategory {
    /// Categories surfaced in the Reference page filter and the freestanding
    /// "Add Feat" picker. `System` entries are synthetic, only meaningful as
    /// `ReplaceWith::Category(System(_))` filter targets.
    pub const USER_FACING: &'static [Self] = &[
        Self::Class,
        Self::Origin,
        Self::General,
        Self::FightingStyle,
        Self::EpicBoon,
        Self::Generation,
        Self::Faction,
        Self::Dragonmark,
    ];
}

impl fmt::Display for FeatureCategory {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Class => f.write_str("Class"),
            Self::Origin => f.write_str("Origin"),
            Self::General => f.write_str("General"),
            Self::FightingStyle => f.write_str("FightingStyle"),
            Self::EpicBoon => f.write_str("EpicBoon"),
            Self::Generation => f.write_str("Generation"),
            Self::Faction => f.write_str("Faction"),
            Self::Dragonmark => f.write_str("Dragonmark"),
            Self::System(slot) => write!(f, "System.{slot}"),
        }
    }
}

impl FromStr for FeatureCategory {
    type Err = ();

    fn from_str(s: &str) -> Result<Self, ()> {
        if let Some(rest) = s.strip_prefix("System.") {
            return rest
                .parse::<IdentitySlot>()
                .map(Self::System)
                .map_err(|_| ());
        }
        match s {
            "Class" => Ok(Self::Class),
            "Origin" => Ok(Self::Origin),
            "General" => Ok(Self::General),
            "FightingStyle" => Ok(Self::FightingStyle),
            "EpicBoon" => Ok(Self::EpicBoon),
            "Generation" => Ok(Self::Generation),
            "Faction" => Ok(Self::Faction),
            "Dragonmark" => Ok(Self::Dragonmark),
            _ => Err(()),
        }
    }
}

impl Serialize for FeatureCategory {
    fn serialize<S: serde::Serializer>(&self, ser: S) -> Result<S::Ok, S::Error> {
        match self {
            Self::System(slot) => {
                use serde::ser::SerializeMap;
                let mut map = ser.serialize_map(Some(1))?;
                map.serialize_entry("System", slot)?;
                map.end()
            }
            other => ser.serialize_str(&other.to_string()),
        }
    }
}

impl<'de> Deserialize<'de> for FeatureCategory {
    fn deserialize<D: serde::Deserializer<'de>>(de: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Repr {
            Tagged {
                #[serde(rename = "System")]
                system: IdentitySlot,
            },
            Bare(String),
        }
        match Repr::deserialize(de)? {
            Repr::Tagged { system } => Ok(Self::System(system)),
            Repr::Bare(s) => s
                .parse()
                .map_err(|_| serde::de::Error::custom(format!("unknown feature category: {s}"))),
        }
    }
}

impl Translatable for FeatureCategory {
    fn tr_key(&self) -> &'static str {
        match self {
            Self::Class => "feat-cat-class",
            Self::Origin => "feat-cat-origin",
            Self::General => "feat-cat-general",
            Self::FightingStyle => "feat-cat-fighting-style",
            Self::EpicBoon => "feat-cat-epic-boon",
            Self::Generation => "feat-cat-generation",
            Self::Faction => "feat-cat-faction",
            Self::Dragonmark => "feat-cat-dragonmark",
            Self::System(IdentitySlot::Subclass) => "feat-cat-system-subclass",
            Self::System(IdentitySlot::Species) => "feat-cat-system-species",
            Self::System(IdentitySlot::Background) => "feat-cat-system-background",
            Self::System(IdentitySlot::Class) => "feat-cat-system-class",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default, Store)]
pub struct Feature {
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub label: Option<String>,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub applied: bool,
    #[serde(default)]
    pub category: FeatureCategory,
    #[serde(default)]
    pub source: FeatureSource,
    #[serde(default)]
    pub inputs: Vec<AssignInputs>,
}

impl Feature {
    pub fn label(&self) -> &str {
        self.label.as_deref().unwrap_or(&self.name)
    }

    pub fn set_label(&mut self, value: String) {
        self.label = Some(value);
    }

    pub fn dom_id(&self) -> String {
        feature_dom_id(&self.name, &self.source)
    }
}

pub fn feature_dom_id(name: &str, source: &FeatureSource) -> String {
    let mut h = DefaultHasher::new();
    name.hash(&mut h);
    source.hash(&mut h);
    format!("f-{:016x}", h.finish())
}

#[derive(
    Debug,
    Clone,
    Hash,
    PartialEq,
    Eq,
    PartialOrd,
    Ord,
    Serialize,
    Deserialize
)]
pub enum FeatureSource {
    Class(Box<str>, u32),
    Subclass(Box<str>, Box<str>, u32),
    #[serde(alias = "Race")]
    Species(Box<str>),
    Background(Box<str>),
    User(u32),
}

impl Default for FeatureSource {
    fn default() -> Self {
        Self::User(0)
    }
}

impl fmt::Display for FeatureSource {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Class(name, level) => write!(f, "Class: {name} ({level})"),
            Self::Subclass(class_name, subclass_name, level) => {
                write!(f, "Subclass: {class_name} - {subclass_name} ({level})")
            }
            Self::Species(name) => write!(f, "Species: {name}"),
            Self::Background(name) => write!(f, "Background: {name}"),
            Self::User(level) => write!(f, "User ({level})"),
        }
    }
}

impl FeatureSource {
    pub fn display_name(&self, i18n: I18n) -> Option<String> {
        match self {
            Self::Class(name, level) => {
                let prefix = tr!(i18n, "source-class");
                Some(format!("{prefix}: {name} ({level})"))
            }
            Self::Subclass(class, name, level) => {
                let prefix = tr!(i18n, "source-subclass");
                Some(format!("{prefix}: {class} — {name} ({level})"))
            }
            Self::Species(name) => {
                let prefix = tr!(i18n, "source-species");
                Some(format!("{prefix}: {name}"))
            }
            Self::Background(name) => {
                let prefix = tr!(i18n, "source-background");
                Some(format!("{prefix}: {name}"))
            }
            Self::User(_) => None,
        }
    }

    pub fn name(&self) -> &str {
        match self {
            Self::Class(name, _)
            | Self::Species(name)
            | Self::Background(name)
            | Self::Subclass(_, name, _) => name,
            Self::User(_) => "",
        }
    }

    pub fn is_user(&self) -> bool {
        matches!(self, Self::User(_))
    }

    pub fn as_class(&self) -> Option<&str> {
        match self {
            Self::Class(name, _) => Some(name),
            Self::Subclass(name, _, _) => Some(name),
            _ => None,
        }
    }

    pub fn added_at_level(&self) -> u32 {
        match self {
            Self::Class(_, level) | Self::User(level) | Self::Subclass(_, _, level) => *level,
            Self::Species(_) | Self::Background(_) => 1,
        }
    }
}

/// Container joining the applied feature list with per-feature data
/// (fields + spells). Co-located because the two are tightly coupled —
/// `data` entries are keyed by feature name and should exist for every
/// applied feature that has fields or spells.
///
/// `Deref`/`DerefMut` target the `BTreeMap<String, FeatureData>` data map
/// so map-style access (`.get()`, `.get_mut()`, `.insert()`, `.keys()`,
/// `.values()`, `.clear()`) works through the container directly. List
/// iteration and list-specific queries go through inherent methods
/// (`iter`, `contains`, `has`, `is_pending`, `add`, `get_inputs`,
/// `has_category`) which override the BTreeMap accessors where names
/// clash.
#[derive(Debug, Clone, Default, Serialize, Deserialize, Store)]
pub struct Features {
    #[serde(default)]
    pub list: Vec<Feature>,
    #[serde(
        default,
        deserialize_with = "crate::serde_util::deserialize_map_dropping_nulls"
    )]
    data: BTreeMap<String, FeatureData>,
}

impl Deref for Features {
    type Target = BTreeMap<String, FeatureData>;

    fn deref(&self) -> &Self::Target {
        &self.data
    }
}

impl DerefMut for Features {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.data
    }
}

impl<'a> IntoIterator for &'a Features {
    type IntoIter = std::slice::Iter<'a, Feature>;
    type Item = &'a Feature;

    fn into_iter(self) -> Self::IntoIter {
        self.list.iter()
    }
}

impl<'a> IntoIterator for &'a mut Features {
    type IntoIter = std::slice::IterMut<'a, Feature>;
    type Item = &'a mut Feature;

    fn into_iter(self) -> Self::IntoIter {
        self.list.iter_mut()
    }
}

impl Features {
    /// Construct from an existing list + data pair. Only used in tests where
    /// struct literals would otherwise need access to the private `data`
    /// field.
    #[cfg(test)]
    pub fn from_parts(list: Vec<Feature>, data: BTreeMap<String, FeatureData>) -> Self {
        Self { list, data }
    }

    /// Iterate applied feature list (overrides BTreeMap::iter from Deref).
    pub fn iter(&self) -> std::slice::Iter<'_, Feature> {
        self.list.iter()
    }

    /// Mutable iter over list (overrides BTreeMap::iter_mut from Deref).
    pub fn iter_mut(&mut self) -> std::slice::IterMut<'_, Feature> {
        self.list.iter_mut()
    }

    /// Does this feature definition + source already have an applied instance?
    /// Non-stackable: any applied by name → true.
    /// Stackable: applied with same name AND source → true.
    pub fn contains(&self, name: &str, stackable: bool, source: &FeatureSource) -> bool {
        if stackable {
            self.list
                .iter()
                .any(|feature| feature.name == name && feature.applied && feature.source == *source)
        } else {
            self.list
                .iter()
                .any(|feature| feature.name == name && feature.applied)
        }
    }

    pub fn has(&self, name: &str) -> bool {
        self.list
            .iter()
            .any(|feature| feature.name == name && feature.applied)
    }

    pub fn has_category(&self, category: FeatureCategory) -> bool {
        self.list
            .iter()
            .any(|feature| feature.applied && feature.category == category)
    }

    /// True if no applied entries at all, or has an unapplied entry waiting.
    pub fn is_pending(&self, name: &str) -> bool {
        let mut has_applied = false;
        let mut has_unapplied = false;
        for feature in &self.list {
            if feature.name == name {
                if feature.applied {
                    has_applied = true;
                } else {
                    has_unapplied = true;
                }
            }
        }
        !has_applied || has_unapplied
    }

    /// Look up stored inputs for a feature by (name, source). Required for
    /// stackable features (e.g. Expertise at Rogue L1 and L6).
    pub fn get_inputs(&self, name: &str, source: &FeatureSource) -> &[AssignInputs] {
        self.list
            .iter()
            .find(|feature| feature.name == name && &feature.source == source)
            .map(|feature| feature.inputs.as_slice())
            .unwrap_or_default()
    }

    /// Add a feature with its inputs. Finds an unapplied entry and fills it
    /// in, or pushes a new applied entry.
    pub fn add(
        &mut self,
        name: &str,
        label: Option<String>,
        description: String,
        category: FeatureCategory,
        source: FeatureSource,
        inputs: Vec<AssignInputs>,
    ) {
        if let Some(feature) = self
            .list
            .iter_mut()
            .rfind(|feature| feature.name == name && !feature.applied)
        {
            feature.applied = true;
            feature.label = label;
            feature.description = description;
            feature.category = category;
            feature.source = source;
            feature.inputs = inputs;
        } else {
            self.list.push(Feature {
                name: name.to_string(),
                label,
                description,
                applied: true,
                category,
                source,
                inputs,
            });
        }
    }

    /// Remove the feature instance matching `name` + `source` from the
    /// list. If no other entries share the name, also drop its `data`
    /// entry (fields + spells). Returns `true` if a match was found.
    pub fn remove(&mut self, name: &str, source: &FeatureSource) -> bool {
        let Some(idx) = self
            .list
            .iter()
            .position(|feature| feature.name == name && &feature.source == source)
        else {
            return false;
        };
        self.list.remove(idx);
        if !self
            .list
            .iter()
            .any(|feature| feature.name == name && feature.applied)
        {
            self.data.remove(name);
        }
        true
    }

    /// Truncate the feature list at the position of the entry matching
    /// `name` + `source`, dropping that feature and everything after it.
    /// Returns `true` if a match was found. Does not touch `data` — callers
    /// typically follow with `Character::reset_computed` + `replay`.
    pub fn truncate(&mut self, name: &str, source: &FeatureSource) -> bool {
        let Some(idx) = self
            .list
            .iter()
            .position(|feature| feature.name == name && &feature.source == source)
        else {
            return false;
        };
        self.list.truncate(idx);
        true
    }

    // Raw data accessors for explicit BTreeMap access where Deref coercion
    // isn't convenient (e.g. cloning, passing as function argument).

    pub fn data(&self) -> &BTreeMap<String, FeatureData> {
        &self.data
    }

    pub fn data_mut(&mut self) -> &mut BTreeMap<String, FeatureData> {
        &mut self.data
    }

    /// Split-borrow `list` and `data` simultaneously so callers can read a
    /// feature name from `list` while mutating its `data` entry.
    pub fn split_mut(&mut self) -> (&[Feature], &mut BTreeMap<String, FeatureData>) {
        (&self.list, &mut self.data)
    }

    // Per-feature data helpers.

    /// Shorthand for `data.get(name).and_then(|e| e.spells.as_ref())`.
    pub fn spell_data(&self, name: &str) -> Option<&SpellData> {
        self.data.get(name).and_then(|e| e.spells.as_ref())
    }

    /// Shorthand for `data.get_mut(name).and_then(|e| e.spells.as_mut())`.
    pub fn spell_data_mut(&mut self, name: &str) -> Option<&mut SpellData> {
        self.data.get_mut(name).and_then(|e| e.spells.as_mut())
    }

    /// Zero `used` on every Points/Die field and every spell's `free_uses`
    /// across all data entries. Used by `Character::long_rest`.
    pub fn reset_uses(&mut self) {
        for entry in self.data.values_mut() {
            for field in &mut entry.fields {
                match &mut field.value {
                    FeatureValue::Points { used, .. } | FeatureValue::Die { used, .. } => {
                        *used = 0;
                    }
                    _ => {}
                }
            }
            if let Some(spell_data) = entry.spells.as_mut() {
                for spell in &mut spell_data.spells {
                    if let Some(fu) = spell.free_uses.as_mut() {
                        fu.used = 0;
                    }
                }
            }
        }
    }

    /// Clear labels and descriptions on list entries and all data fields/
    /// spells. Used by `Character::clear_all_labels`.
    pub fn clear_all_labels(&mut self) {
        for feature in &mut self.list {
            feature.label = None;
            feature.description.clear();
        }
        for entry in self.data.values_mut() {
            for field in &mut entry.fields {
                field.label = None;
                field.description.clear();
                for opt in field.value.choices_mut() {
                    opt.label = None;
                    opt.description.clear();
                }
            }
            if let Some(spells) = &mut entry.spells {
                for spell in &mut spells.spells {
                    spell.label = None;
                    spell.description.clear();
                }
                for spell in spells.known.iter_mut().flatten() {
                    spell.label = None;
                    spell.description.clear();
                }
            }
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default, Store)]
pub struct AssignInputs {
    #[serde(default)]
    pub args: Vec<i32>,
    #[serde(default)]
    pub dice: DicePool,
}

impl AssignInputs {
    pub fn is_empty(&self) -> bool {
        self.args.is_empty() && self.dice.is_empty()
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default, Store)]
pub struct FeatureData {
    #[serde(default)]
    pub fields: Vec<FeatureField>,
    #[serde(default)]
    pub spells: Option<SpellData>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Store)]
pub struct FeatureField {
    pub name: String,
    #[serde(default)]
    pub label: Option<String>,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub value: FeatureValue,
}

impl FeatureField {
    pub fn label(&self) -> &str {
        self.label.as_deref().unwrap_or(&self.name)
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Store)]
pub enum FeatureValue {
    Points { used: u32, max: u32 },
    Choice { options: Vec<FeatureOption> },
    Die { die: Die, used: u32 },
    Bonus(i32),
}

impl Default for FeatureValue {
    fn default() -> Self {
        FeatureValue::Points { used: 0, max: 0 }
    }
}

/// Derive a short abbreviation from a name by taking the first letter of each
/// word. "Channel Divinity" → "CD", "Sorcery Points" → "SP", "Rages" → "R"
pub fn short_name(name: &str) -> String {
    name.split_whitespace()
        .filter_map(|w| w.chars().next())
        .flat_map(char::to_uppercase)
        .collect()
}

impl FeatureValue {
    pub fn available_points(&self) -> Option<u32> {
        match self {
            FeatureValue::Points { used, max } => Some(max.saturating_sub(*used)),
            FeatureValue::Die { die, used } => Some(die.amount.saturating_sub(*used)),
            _ => None,
        }
    }

    pub fn max_points(&self) -> Option<u32> {
        match self {
            FeatureValue::Points { max, .. } => Some(*max),
            FeatureValue::Die { die, .. } => Some(die.amount),
            _ => None,
        }
    }

    pub fn choices(&self) -> &[FeatureOption] {
        match self {
            FeatureValue::Choice { options } => options,
            _ => &[],
        }
    }

    pub fn choices_mut(&mut self) -> &mut [FeatureOption] {
        match self {
            FeatureValue::Choice { options } => options,
            _ => &mut [],
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default, Store)]
pub struct FeatureOption {
    pub name: String,
    #[serde(default)]
    pub label: Option<String>,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub cost: u32,
    /// Set when this option is an action menu item (e.g. Innate Sorcery cast
    /// button). `None` for stored-choice picks. Filled by `sync_labels` from
    /// the registry definition; persisted so renderers don't need a
    /// `feat.actions` lookup.
    #[serde(default)]
    pub action: Option<ActionType>,
}

impl FeatureOption {
    pub fn label(&self) -> &str {
        self.label.as_deref().unwrap_or(&self.name)
    }

    pub fn set_label(&mut self, value: String) {
        self.label = Some(value);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn features_data_drops_null_entries() {
        let json = serde_json::json!({
            "list": [],
            "data": {
                "Tough": null,
                "Versatile": { "fields": [], "spells": null }
            }
        });
        let features: Features = serde_json::from_value(json).expect("deserialize");
        assert!(!features.data.contains_key("Tough"));
        assert!(features.data.contains_key("Versatile"));
    }
}
